118	        assertThat(current.version()).isEqualTo(3);
119	        assertThat(current.location()).isEqualTo("站点C");
120	        Integer versionRows = jdbcTemplate.queryForObject(
121	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-x1'", Integer.class);
122	        assertThat(versionRows).isEqualTo(3);
123	        Integer resolutionRows = jdbcTemplate.queryForObject(
124	                "SELECT COUNT(*) FROM conflict_resolution WHERE observation_id = 'obs-x1'", Integer.class);
125	        assertThat(resolutionRows).isEqualTo(1);
126	        // 两个不同 requestId 中只有成功方占位落库；失败事务回滚，不占 requestId
127	        Integer totalRequestRows = jdbcTemplate.queryForObject(
128	                "SELECT COUNT(*) FROM request_log WHERE request_id IN ('req-x1-a','req-x1-b')", Integer.class);
