    @Test
    void concurrentCreatesOnSameObservationIdYieldSingleRecord() throws Exception {
        List<Callable<String>> tasks = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            final int index = i;
            tasks.add(() -> {
                try {
                    observationService.create(new CreateObservationRequest(
