        submit("req-f3", "obs-2", "DEV-1", 6);
        // 服务端先把 obs-2 的地点合并为站点X（版本 2）
        Map<String, Object> mergeBody = new LinkedHashMap<>();
        mergeBody.put("requestId", "req-f4");
